\title{The Secret Number Theory of the Mandelbrot Set:\\
Quadratic Escape, the Doubling Map, and Farey--Fibonacci Bulb Ordering}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
The Mandelbrot set $M$ is the set of complex parameters $c$ for which the critical orbit of the
quadratic map $f_c(z) = z^2 + c$ remains bounded. Its intricate boundary is decorated by hyperbolic
components (``bulbs'') indexed by rational \emph{external angles} $p/q \in \Q/\Z$. We develop a
self-contained account of the elementary but genuinely quantitative dynamics of the recurrence
$z_{n+1} = z_n^2 + c$, and of the number theory that governs the arrangement of the bulbs. We prove:
(i) an escape--radius theorem, $M \subseteq \{\norm{c} \le 2\}$, via a geometric growth bound on the
critical orbit; (ii) that the angle-doubling map $\theta \mapsto 2\theta \bmod 1$ restricted to
denominator $q$ is multiplication by $2$ on $\Z/q\Z$, a bijection if and only if $q$ is odd, so that
$p/q$ is purely periodic iff $q$ is odd; (iii) that the period of the angle $1/q$ equals the
multiplicative order $\ord_q(2)$, giving a Mersenne-type divisibility $q \mid 2^{\ord_q(2)} - 1$ and,
for odd primes $q$, the Fermat bound $\ord_q(2) \mid q - 1$; and (iv) that the ``golden path'' of
largest satellite bulbs realizes the Fibonacci sequence through the Farey mediant operation, with
consecutive Fibonacci ratios being Farey neighbours by Cassini's identity. We also prove that two
natural conjectures about bulb periods are false.
\end{abstract}

\section{Introduction}
The Mandelbrot set is generated by iterating a quadratic map, yet the arrangement of the decorative
bulbs on its boundary is governed by classical number theory. This paper isolates and proves a
coherent slice of that number theory, keeping every argument elementary and self-contained.

We work with the quadratic family $f_c(z) = z^2 + c$ ($c, z \in \C$) and its \emph{critical orbit}
$O_c = (f_c^{(n)}(0))_{n \ge 0}$, the orbit of the critical point $0$. The Mandelbrot set is
\[
M = \{\, c \in \C : O_c \text{ is bounded} \,\}
  = \{\, c : \exists B,\ \forall n,\ \norm{f_c^{(n)}(0)} \le B \,\}.
\]
Three themes are developed in turn: quantitative escape (Section~\ref{sec:escape}); external angles
and the doubling map (Section~\ref{sec:doubling}); and the Farey--Fibonacci bulb ordering
(Section~\ref{sec:farey}). A contrarian section (Section~\ref{sec:contrarian}) refutes two tempting
conjectures.

\section{Preliminaries and Notation}
For $z \in \C$, $\norm{z}$ denotes the modulus. For $q \ge 1$, $\Z/q\Z$ is the ring of integers
modulo $q$, and for a unit $a$, $\ord_q(a)$ is its multiplicative order. We write $\varphi$ for
Euler's totient. The Fibonacci numbers are $F_0 = 0$, $F_1 = 1$, $F_{n+2} = F_{n+1} + F_n$. We write
$f_c^{(n)}$ for the $n$-fold composition, so $f_c^{(n+1)}(0) = (f_c^{(n)}(0))^2 + c$.

\section{Quantitative Escape and the Escape Radius}\label{sec:escape}

\begin{lemma}[Step lower bound]\label{lem:step}
For all $c, z \in \C$, $\ \norm{z}^2 - \norm{c} \le \norm{z^2 + c}$.
\end{lemma}
\begin{proof}
By the reverse triangle inequality, $\norm{z^2 + c} = \norm{z^2 - (-c)} \ge \norm{z^2} - \norm{-c}
= \norm{z}^2 - \norm{c}$, using $\norm{z^2} = \norm{z}^2$.
\end{proof}

\begin{proposition}[Growth invariant]\label{prop:growth}
If $\norm{c} > 2$, then for every $n \ge 0$,
\[
\norm{c} \le \norm{f_c^{(n+1)}(0)} \qquad\text{and}\qquad
\norm{c}\,(\norm{c} - 1)^n \le \norm{f_c^{(n+1)}(0)}.
\]
\end{proposition}
\begin{proof}
Induct on $n$. For $n = 0$, $f_c^{(1)}(0) = c$ and both read $\norm{c} \le \norm{c}$. Assume both at
$n$ and set $r = \norm{f_c^{(n+1)}(0)} \ge \norm{c} > 2$. By Lemma~\ref{lem:step},
$\norm{f_c^{(n+2)}(0)} \ge r^2 - \norm{c}$. Since $r > 2$ and $r \ge \norm{c}$, we have
$r^2 - \norm{c} \ge \norm{c}(r-1) \ge \norm{c}$, giving the first inequality; combining with
$r \ge \norm{c}(\norm{c}-1)^n$ yields $\norm{f_c^{(n+2)}(0)} \ge \norm{c}(\norm{c}-1)^{n+1}$.
\end{proof}

\begin{theorem}[Escape]\label{thm:escape}
If $\norm{c} > 2$, then $\norm{f_c^{(n)}(0)} \to \infty$ as $n \to \infty$.
\end{theorem}
\begin{proof}
Since $\norm{c} - 1 > 1$, the sequence $\norm{c}(\norm{c}-1)^n \to +\infty$; by
Proposition~\ref{prop:growth} the orbit norm dominates it.
\end{proof}

\begin{theorem}[Escape radius]\label{thm:radius}
$M \subseteq \{\, c : \norm{c} \le 2 \,\}$.
\end{theorem}
\begin{proof}
If $c \in M$ the orbit is bounded by some $B$; were $\norm{c} > 2$, Theorem~\ref{thm:escape} would
push the orbit norm above $B$, a contradiction.
\end{proof}

\begin{corollary}[Concrete membership]
$0 \in M$ (orbit constantly $0$) and $-1 \in M$ (orbit the $2$-cycle $0,-1,0,-1,\dots$), while
$3 \notin M$ since $\norm{3} = 3 > 2$.
\end{corollary}

\section{External Angles and the Doubling Map}\label{sec:doubling}
Hyperbolic components of $M$ are indexed by rational external angles $p/q$, and the boundary dynamics
is the doubling map $\theta \mapsto 2\theta \bmod 1$. Restricted to denominator $q$ it acts on
$\Z/q\Z$ by $dbl_q(x) = 2x \bmod q$.

\begin{lemma}[Iterates]\label{lem:iter}
For all $n$ and $x \in \Z/q\Z$, $\ dbl_q^{(n)}(x) = 2^n x$.
\end{lemma}
\begin{proof}
Induction: $dbl_q^{(0)}(x) = x = 2^0 x$ and $dbl_q^{(n+1)}(x) = 2\cdot 2^n x = 2^{n+1} x$.
\end{proof}

\begin{theorem}[Bijectivity iff odd]\label{thm:oddeven}
$dbl_q$ is a bijection on $\Z/q\Z$ iff $q$ is odd. If $q$ is even and positive, $dbl_q$ is not
injective.
\end{theorem}
\begin{proof}
If $q$ is odd, $\gcd(2,q)=1$, so $2$ is a unit (indeed $u=(q+1)/2$ satisfies $2u \equiv 1$), and
$x \mapsto ux$ inverts $dbl_q$. If $q = 2k$ with $k \ge 1$, then $dbl_q(0) = 0 = dbl_q(k)$ but
$0 \ne k$ in $\Z/q\Z$.
\end{proof}

The angle $p/q$ is purely periodic under doubling exactly when $q$ is odd; even $q$ yields merely
pre-periodic rays.

\begin{corollary}[Common period]
If $q > 1$ is odd, then $dbl_q^{(\varphi(q))} = \mathrm{id}$ with $\varphi(q) > 0$.
\end{corollary}
\begin{proof}
Euler's theorem gives $2^{\varphi(q)} \equiv 1 \pmod q$; apply Lemma~\ref{lem:iter}.
\end{proof}

\begin{theorem}[Period of $1/q$]\label{thm:period}
For every $n$, $\ dbl_q^{(n)}(1) = 1 \iff \ord_q(2) \mid n$. Hence the period of $1/q$ equals
$\ord_q(2)$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:iter}, $dbl_q^{(n)}(1) = 2^n$, and $2^n = 1$ in $\Z/q\Z$ iff $\ord_q(2) \mid n$.
\end{proof}

\begin{theorem}[Mersenne-type divisibility]
For all $q \ge 1$, $\ q \mid 2^{\ord_q(2)} - 1$. For odd $q > 1$ the exponent is a genuine positive
period; for even $q$ the order is $0$ and $q \mid 0$.
\end{theorem}
\begin{proof}
By definition $2^{\ord_q(2)} \equiv 1 \pmod q$.
\end{proof}

\begin{theorem}[Fermat bound]
If $q$ is an odd prime, then $\ord_q(2) \mid q - 1$.
\end{theorem}
\begin{proof}
Fermat's little theorem gives $2^{q-1} \equiv 1 \pmod q$; apply Theorem~\ref{thm:period} with
$n = q-1$.
\end{proof}

\section{Farey Mediants, Fibonacci, and the Bulb Ordering}\label{sec:farey}

\begin{definition}[Mediant]
For pairs $(p,q)$ and $(p',q')$, $\ \med((p,q),(p',q')) = (p+p',\, q+q')$.
\end{definition}
Fractions $p/q$ and $p'/q'$ are \emph{Farey neighbours} when $|pq' - p'q| = 1$; the mediant labels
the largest bulb wedged between the two corresponding bulbs. The golden path of largest satellites
realizes $F_n/F_{n+1}$.

\begin{theorem}[Fibonacci as iterated mediants]\label{thm:fibmed}
For all $n \ge 0$, $\ \med((F_n, F_{n+1}), (F_{n+1}, F_{n+2})) = (F_{n+2}, F_{n+3})$.
\end{theorem}
\begin{proof}
$(F_n + F_{n+1},\ F_{n+1} + F_{n+2}) = (F_{n+2},\ F_{n+3})$ by the recurrence.
\end{proof}

\begin{theorem}[Cassini's identity]\label{thm:cassini}
For all $n \ge 0$, $\ F_{n+1}^2 - F_n F_{n+2} = (-1)^n$.
\end{theorem}
\begin{proof}
Induction. Base: $F_1^2 - F_0 F_2 = 1 = (-1)^0$. Step: using $F_{n+3}=F_{n+2}+F_{n+1}$ and
$F_{n+2}=F_{n+1}+F_n$,
\[
F_{n+2}^2 - F_{n+1}F_{n+3} = F_{n+2}(F_{n+2}-F_{n+1}) - F_{n+1}^2 = F_{n+2}F_n - F_{n+1}^2 =
(-1)^{n+1}.
\]
\end{proof}

\begin{corollary}[Unimodularity]
For all $n \ge 0$, $|F_{n+1}^2 - F_n F_{n+2}| = 1$; consecutive Fibonacci ratios are Farey
neighbours.
\end{corollary}

\begin{theorem}[Lowest terms]
For all $n \ge 0$, $\gcd(F_n, F_{n+1}) = 1$; each ratio $F_n/F_{n+1}$ is in lowest terms.
\end{theorem}
\begin{proof}
$\gcd(F_0,F_1)=1$ and $\gcd(F_{n+1},F_{n+2}) = \gcd(F_{n+1},F_n) = \gcd(F_n,F_{n+1})$.
\end{proof}

\begin{proposition}[Shrinking denominators]
For $n \ge 1$, $F_{n+1} < F_{n+2}$; the bulbs along the golden path shrink.
\end{proposition}

The ratios $F_n/F_{n+1} \to 1/\varphi = (\sqrt5-1)/2 \approx 0.618$, so the golden path accumulates
at the external angle of the reciprocal golden mean.

\section{Contrarian Section: Two False Conjectures}\label{sec:contrarian}
We record $\ord_3(2) = 2$, $\ord_5(2) = 4$, $\ord_7(2) = 3$.

\begin{theorem}[$2$ is not always a primitive root]
There is an odd prime $q$ with $\ord_q(2) \ne q - 1$: for $q = 7$, $\ord_7(2) = 3 \ne 6$.
\end{theorem}

\begin{theorem}[Bulb periods are not always prime]
There is an odd prime $q$ with $\ord_q(2)$ composite: for $q = 5$, $\ord_5(2) = 4$.
\end{theorem}

\section{Future Directions}
(1) Landing of external rays: connect $p/q$ to genuine hyperbolic components via Böttcher
coordinates. (2) Period vs.\ order for general $p/q$ and full pre-period analysis for even
denominators. (3) Maximal period and Artin's conjecture on $2$ as a primitive root. (4) Sharper
escape geometry toward the connectedness locus and cardioid bounds. (5) The golden-mean rotation
number and continued fractions.

\section{Conclusion}
From a single quadratic feedback rule we extracted a coherent arithmetic skeleton: an escape bound
confining $M$ to a disk of radius $2$; a reduction of boundary dynamics to multiplication by $2$
modulo $q$ with an exact odd/even periodicity dichotomy; the identification of bulb periods with
multiplicative orders, yielding Mersenne divisibility and Fermat's bound; explicit counterexamples;
and the Farey--Fibonacci ordering sending the largest bulbs toward the golden mean.

\end{document}

