from typing import List, Optional

def critical_orbit(c: complex, steps: int) -> List[complex]:
    orbit: List[complex] = [0j]; z = 0j
    for _ in range(steps):
        z = z * z + c; orbit.append(z)
    return orbit

def escape_step(c: complex, cap: int = 1000) -> Optional[int]:
    z = 0j
    for k in range(1, cap + 1):
        z = z * z + c
        if abs(z) > 2.0:
            return k
    return None

for c in [0j, -1+0j, -0.75+0.1j, 0.26+0j, 3+0j, 1+1j]:
    k = escape_step(c)
    print(c, "|c|=%.3f" % abs(c),
          "BOUNDED" if k is None else "escaped@%d" % k)
print("orbit of -1:", [round(z.real, 3) for z in critical_orbit(-1+0j, 5)])

from math import gcd
from typing import Optional

def is_bijective_doubling(q: int) -> bool:
    return len({(2 * x) % q for x in range(q)}) == q

def order2(q: int) -> Optional[int]:
    if q <= 1 or gcd(2, q) != 1: return None
    r, n = 1, 0
    while True:
        r = (2 * r) % q; n += 1
        if r == 1: return n

def is_prime(n: int) -> bool:
    return n > 1 and all(n % i for i in range(2, int(n**0.5) + 1))

for q in range(2, 13):
    print("q=%2d %s bijective=%s" %
          (q, "odd " if q % 2 else "even", is_bijective_doubling(q)))
for q in [3, 5, 7, 9, 11, 13, 17]:
    o = order2(q)
    fer = " Fermat:%s" % ((q-1) % o == 0) if is_prime(q) else ""
    print("q=%2d ord=%2d  Mersenne:%s%s" % (q, o, (2**o - 1) % q == 0, fer))

from math import gcd
from typing import Tuple

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

def mediant(a: Tuple[int,int], b: Tuple[int,int]) -> Tuple[int,int]:
    return (a[0]+b[0], a[1]+b[1])

def cassini(n: int) -> int:
    return fib(n+1)**2 - fib(n)*fib(n+2)

for n in range(1, 9):
    p, q = fib(n), fib(n+1)
    print("F%d/F%d = %d/%d = %.6f gcd=%d" % (n, n+1, p, q, p/q, gcd(p, q)))
print("limit 1/phi =", (5**0.5 - 1) / 2)
for n in range(6):
    print("med", mediant((fib(n),fib(n+1)),(fib(n+1),fib(n+2))),
          "cassini=%+d" % cassini(n))

